function Logo({ dark = false }: { dark?: boolean }) { return <Link to="/" className="flex items-center gap-2.5"><span className={`grid h-9 w-9 place-items-center rounded-xl ${dark ? 'bg-violet-500' : 'bg-white/10'} shadow-lg shadow-violet-500/20`}><Sparkles size={18} /></span><span className="display text-lg font-semibold tracking-tight">Rate<span className="text-violet-300">Space</span></span></Link> }

function Ambient({ compact = false }: { compact?: boolean }) { return <div className={`pointer-events-none absolute inset-0 overflow-hidden ${compact ? 'rounded-[inherit]' : ''}`}><div className="blob absolute -left-32 -top-32 h-96 w-96 rounded-full bg-violet-600/20 blur-[100px]"/><div className="blob-reverse absolute -right-40 top-1/3 h-[34rem] w-[34rem] rounded-full bg-cyan-500/10 blur-[120px]"/><div className="absolute bottom-0 left-1/3 h-80 w-80 rounded-full bg-fuchsia-500/10 blur-[120px]"/></div> }

function Button({ children, variant = 'primary', className = '', onClick, to }: { children: React.ReactNode; variant?: 'primary' | 'secondary' | 'ghost'; className?: string; onClick?: () => void; to?: string }) {
  const styles = variant === 'primary' ? 'bg-white text-slate-950 hover:bg-violet-100 shadow-xl shadow-violet-500/10' : variant === 'secondary' ? 'glass-soft text-white hover:bg-white/12' : 'text-white/60 hover:bg-white/8 hover:text-white'
  const content = <motion.span whileHover={{ scale: 1.02 }} whileTap={{ scale: .98 }} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition ${styles} ${className}`}>{children}</motion.span>
  return to ? <Link to={to}>{content}</Link> : <button onClick={onClick}>{content}</button>
}

function Stars({ rating, interactive = false, value, onChange }: { rating?: number; interactive?: boolean; value?: number; onChange?: (value: number) => void }) {
  const active = value ?? Math.round(rating ?? 0)
  return <div className="flex items-center gap-0.5">{[1,2,3,4,5].map(star => interactive ? <motion.button key={star} whileHover={{ scale: 1.2 }} whileTap={{ scale: .9 }} onClick={() => onChange?.(star)} className={`p-0.5 transition ${star <= active ? 'text-amber-300' : 'text-white/20'}`}><Star size={26} fill={star <= active ? 'currentColor' : 'none'} /></motion.button> : <Star key={star} size={13} fill={star <= active ? 'currentColor' : 'none'} className={star <= active ? 'text-amber-300' : 'text-white/20'} />)}</div>
}

